{
  "displayName": "Webhook Conditional Processing",
  "trigger": {
    "name": "trigger",
    "type": "PIECE_TRIGGER",
    "valid": true,
    "displayName": "Webhook Trigger",
    "settings": {
      "pieceName": "@activepieces/piece-webhook",
      "pieceVersion": "~1.0.0",
      "triggerName": "catch_webhook",
      "input": {},
      "propertySettings": {}
    },
    "nextAction": {
      "name": "step_router",
      "type": "ROUTER",
      "valid": true,
      "displayName": "Check Email",
      "settings": {
        "executionType": "EXECUTE_FIRST_MATCH",
        "branches": [
          {
            "branchType": "CONDITION",
            "branchName": "Email Missing",
            "conditions": [
              [
                {
                  "firstValue": "{{trigger.body.email}}",
                  "operator": "DOES_NOT_EXIST"
                }
              ]
            ]
          },
          {
            "branchType": "FALLBACK",
            "branchName": "Email Present"
          }
        ],
        "propertySettings": {}
      },
      "children": [
        {
          "name": "step_slack",
          "type": "PIECE",
          "valid": true,
          "displayName": "Send Slack Alert",
          "settings": {
            "pieceName": "@activepieces/piece-slack",
            "pieceVersion": "~0.9.0",
            "actionName": "send_channel_message",
            "input": {
              "channel": "#ops",
              "text": "\u26a0\ufe0f Webhook received without email: {{trigger.body}}"
            },
            "propertySettings": {}
          }
        },
        {
          "name": "step_sheets",
          "type": "PIECE",
          "valid": true,
          "displayName": "Add to Google Sheets",
          "settings": {
            "pieceName": "@activepieces/piece-google-sheets",
            "pieceVersion": "~0.11.0",
            "actionName": "insert_row",
            "input": {
              "spreadsheetId": "__TODO_SPREADSHEET_ID__",
              "sheetId": "__TODO_SHEET_ID__",
              "values": "{{trigger.body}}"
            },
            "propertySettings": {}
          }
        }
      ]
    }
  },
  "schemaVersion": null
}

{
  "displayName": "Lead Score Routing",
  "trigger": {
    "name": "trigger",
    "type": "PIECE_TRIGGER",
    "valid": true,
    "displayName": "New Row Added",
    "settings": {
      "pieceName": "@activepieces/piece-google-sheets",
      "pieceVersion": "~0.11.0",
      "triggerName": "new_row",
      "input": {
        "spreadsheetId": "__TODO_SPREADSHEET_ID__",
        "sheetId": "__TODO_SHEET_ID__"
      },
      "propertySettings": {}
    },
    "nextAction": {
      "name": "step_router",
      "type": "ROUTER",
      "valid": true,
      "displayName": "Check Lead Score",
      "settings": {
        "executionType": "EXECUTE_FIRST_MATCH",
        "branches": [
          {
            "branchType": "CONDITION",
            "branchName": "High Score",
            "conditions": [
              [
                {
                  "firstValue": "{{trigger.values.leadScore}}",
                  "secondValue": "80",
                  "operator": "NUMBER_IS_GREATER_THAN_OR_EQUAL_TO"
                }
              ]
            ]
          },
          {
            "branchType": "FALLBACK",
            "branchName": "Low Score"
          }
        ],
        "propertySettings": {}
      },
      "children": [
        {
          "name": "step_email",
          "type": "PIECE",
          "valid": true,
          "displayName": "Send Email",
          "settings": {
            "pieceName": "@activepieces/piece-gmail",
            "pieceVersion": "~0.8.0",
            "actionName": "send_email",
            "input": {
              "receiver": [
                "sales@example.com"
              ],
              "subject": "High Score Lead: {{trigger.values.name}}",
              "body": "Lead Score: {{trigger.values.leadScore}}\nName: {{trigger.values.name}}"
            },
            "propertySettings": {}
          }
        },
        {
          "name": "step_slack",
          "type": "PIECE",
          "valid": true,
          "displayName": "Post to Slack",
          "settings": {
            "pieceName": "@activepieces/piece-slack",
            "pieceVersion": "~0.9.0",
            "actionName": "send_channel_message",
            "input": {
              "channel": "#leads",
              "text": "New lead (score {{trigger.values.leadScore}}): {{trigger.values.name}}"
            },
            "propertySettings": {}
          }
        }
      ]
    }
  },
  "schemaVersion": null
}

